-- Sound probe, control stage (never ships).
--
-- Builds the scene in on_init, because `--create` runs no ticks: anything built on
-- tick 2 would not exist in the save the GUI then loads. Chunks therefore have to be
-- requested and generated by hand first, or create_entity lands on ungenerated map.
--
-- The turret is then put through ignition -> held stream -> shut-down cycles by
-- destroying and re-creating its target, so a GUI run plays the shared begin_sound,
-- the looping middle_sound and the end_sound, several times over.

local TURRET = "melta-turret"
local FLUID = "melta-fuel"
local DUMMY = "snd-dummy"
local CENTRE = {x = 0, y = 300}
local TARGET = {x = 0, y = 293}          -- 7 tiles north: inside the 16 tile reach
local CYCLE = 300                        -- 5 s: 4 s firing, 1 s of silence

local function logf(fmt, ...)
  log("[snd] " .. string.format(fmt, ...))
end

local function set_fluid(turret, amount)
  -- 2.1 has no `fluidbox` attribute on LuaEntity: the API is insert_fluid / clear_fluids
  turret.clear_fluids()
  turret.insert_fluid{name = FLUID, amount = amount}
end

local function build(surface)
  surface.set_tiles({{name = "refined-concrete", position = CENTRE}})
  local turret = surface.create_entity{name = TURRET, position = CENTRE, force = game.forces.player}
  if not turret then
    logf("FAILED to create the turret")
    return
  end
  set_fluid(turret, 100)
  storage.probe = {turret = turret, surface = surface, cycle = 0}

  local dummy = surface.create_entity{name = DUMMY, position = TARGET, force = game.forces.enemy}
  storage.probe.dummy = dummy
  logf("built turret at %s with dummy at %s; fluid=%s",
       serpent.line(CENTRE), serpent.line(TARGET),
       tostring(turret.get_fluid_count(FLUID)))
end

script.on_init(function()
  local surface = game.surfaces[1]
  surface.request_to_generate_chunks(CENTRE, 2)
  surface.request_to_generate_chunks(TARGET, 2)
  surface.force_generate_chunk_requests()
  build(surface)
end)

script.on_nth_tick(60, function()
  local p = storage.probe
  if not p or not p.turret or not p.turret.valid then return end
  local fluid = p.turret.get_fluid_count(FLUID)
  local target = p.turret.shooting_target
  logf("tick %d: fluid=%.1f shooting=%s", game.tick, fluid, target and target.name or "nil")
  if fluid < 30 then
    set_fluid(p.turret, 100)
    logf("tick %d: refilled the fluid box", game.tick)
  end
  if game.tick % CYCLE == 0 then
    p.cycle = p.cycle + 1
    if p.dummy and p.dummy.valid then p.dummy.destroy() end
    p.dummy = p.surface.create_entity{name = DUMMY, position = TARGET, force = game.forces.enemy}
    logf("tick %d: cycle %d -- target replaced, ignition should play again", game.tick, p.cycle)
  end
end)
